```java
@SpringBootTest
@Transactional
class OrderServiceIntegrationTest {

    @Autowired
    private OrderService orderService;

    @Autowired
    private OrderRepository orderRepository;

    @Test
    void shouldCreateOrderAndPersistIt() {
        var order = new Order(null, "Laptop", 1200.00);
        var savedOrder = orderService.createOrder(order);

        assertThat(savedOrder.id()).isNotNull();
        assertThat(orderRepository.findById(savedOrder.id()))
            .isPresent()
            .get()
            .extracting(Order::item)
            .isEqualTo("Laptop");
    }
}
```
*This verifies the real service-to-repository path present in this test context. `@Transactional` rolls back database work performed in the test-managed transaction.*

