// MOCK (default): no real server, drive it with MockMvc
@SpringBootTest // webEnvironment = MOCK by default
@AutoConfigureMockMvc
class MockEnvTest {
    @Autowired MockMvc mockMvc;

    @Test
    void hitsEndpoint() throws Exception {
        mockMvc.perform(get("/api/orders"))
               .andExpect(status().isOk());
    }
}

// RANDOM_PORT: a real server starts, call it with TestRestTemplate
@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
class RandomPortTest {
    @LocalServerPort int port;            // the random port, injected
    @Autowired TestRestTemplate rest;

    @Test
    void callsRealHttp() {
        var body = rest.getForObject(
            "http://localhost:" + port + "/api/orders", String.class);
        assertThat(body).isNotNull();
    }
}
```
*Swap MOCK for RANDOM_PORT the moment you need a real socket — TestRestTemplate has nothing to talk to under MOCK.*

