```java
@SpringBootTest
class OrderServiceIntegrationTest {

    @Autowired
    private OrderService orderService;

    @Autowired
    private OrderRepository orderRepository;

    @MockitoBean
    private PaymentClient paymentClient; // use @MockBean on older Boot

    @Test
    void shouldCreateOrderWithMockedPayment() {
        when(paymentClient.charge(anyDouble())).thenReturn(true);

        var order = orderService.createOrder("laptop", 999.99);

        assertThat(order.getId()).isNotNull();
        verify(paymentClient).charge(999.99);
    }
}
```

