@SpringBootTest
@DirtiesContext // rebuild the context after this class — genuinely needed here
class ConnectionPoolShutdownTest {
    @Autowired DataSource dataSource;

    @Test
    void closesPoolThenNeedsFreshContext() {
        ((HikariDataSource) dataSource).close(); // corrupts the shared context
        // without @DirtiesContext, the next test class reuses a dead pool
    }
}

// Prefer this for DB tests — rollback instead of rebuilding the context
@SpringBootTest
@Transactional // each test rolls back; context stays cached and fast
class OrderRepositoryTest {
    @Autowired OrderRepository repo;

    @Test
    void savesThenRollsBack() {
        repo.save(new Order("Laptop"));
    }
}
